// Регресс «готовность к выпуску 19.10.2026» — группа 1: главная и история.
// Факты: .qa/readiness/2026-10-19/ac-status.md (F-98, F-104 AC3, F-43, F-41 AC3), readiness-report.html («Главная», «История»),
// снимки app/S-01-home-new.txt, S-10-home-3-prayers.txt (3 записи — «צפה בהכל» нет), F-50-kabala.txt (4 записи — есть), S-26-history.txt.
// «צפה בהכל» при >3 и диалог «התפילה כבר נרשמה היום / רשום שוב» — комментарий разработчика к #6a86f7e5 (24.09).
// Кейсы: .qa/tests/readiness/RD-01-home-history.md. Дополняет HM-02 (наличие «צפה בהכל») и PH-01 (данные USER1).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, scrollToText } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { deviceClock } from '../_lib/app-1310b.ts';
import {
  goHome, counter, newestRecentPrayer, nodes, button, labelOf, openCatalogPrayer, tapFinish, recordAllowed,
  REPEAT_TITLE, REPEAT_AGAIN, FINISH_TITLE, BACK_HOME, visibleActionButtons, headerTap, shownNusach,
} from '../_lib/readiness-1910.ts';

const ROW_RE = /^(שחרית|מנחה|ערבית|[א-ת ]+), (.+), \d{2}:\d{2}(:\d{2})?$/;
const GROUP_RE = /^[א-ת״׳' ]+ · \d{1,2} [א-ת]+׳?$/;

async function openHistory() {
  await goHome();
  await (await scrollToText('צפה בהכל')).click();
  await (await byText('היסטוריית התפילות שלי')).waitForDisplayed({ timeout: 20000 });
}
async function historyRows() {
  return (await nodes()).filter((n) => ROW_RE.test(n.label) && n.visible).map((n) => n.label);
}
async function historyGroups() {
  return (await nodes()).filter((n) => GROUP_RE.test(n.label) && n.visible).map((n) => n.label);
}
async function setHistorySearch(t: string) {
  const f = await byLabel('חיפוש');
  await f.clearValue();
  if (t) await f.setValue(t);
}

describe('Готовность 19.10 — главная и история', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('RD-01a «צפה בהכל» на главной только при 4+ записях (при ≤3 нет) и ведёт в «היסטוריית התפילות שלי» #6a86f7e5 F-104 AC3 @prod-safe', async () => {
    await goHome();
    const total = await counter('סה״כ תפילות');
    if (total === 0) {
      // Пустой аккаунт: карточка «התחל את המסע שלך», блока «תפילות אחרונות» и ссылки нет (F-104 AC5 / F-43 AC3).
      await scrollToText('התחל את המסע שלך');
      expect(await shown(byText('צפה בהכל'))).toBe(false);
      return;
    }
    await scrollToText('תפילות אחרונות');
    await scrollToText('תזכורות מהירות');
    const link = await shown(byText('צפה בהכל'));
    console.log(`[RD-01a] סה״כ תפילות=${total}, «צפה בהכל» видна=${link}`);
    if (total > 3) {
      expect(link).toBe(true);
      await (await byText('צפה בהכל')).click();
      await expect(byText('היסטוריית התפילות שלי')).toBeDisplayed({ wait: 20000 });
      expect(await shown(byText('היסטוריית תפילות שלי'))).toBe(false);   // старое имя (#56d002bd, עבר QA 25.10)
    } else {
      expect(link).toBe(false);   // S-10: 3 записи — ссылки нет (факт 19.10)
    }
  });

  it('RD-01b S-26 «היסטוריית התפילות שלי»: группы «<евр. дата> · <дата>», строки «<тип>, <группа>, HH:mm», поиск по типу и пустой результат #6a86f800 F-43 AC1/AC2/AC4 @prod-safe', async function () {
    await goHome();
    if ((await counter('סה״כ תפילות')) <= 3) skipWith(this, 'нужно 4+ записей, иначе на главной нет «צפה בהכל»');
    await openHistory();
    await driver.waitUntil(async () => (await historyRows()).length > 0, { timeout: 20000, timeoutMsg: 'нет строк истории' });
    const groups = await historyGroups();
    const rows = await historyRows();
    expect(groups.length).toBeGreaterThan(0);
    // Каждая строка содержит дату своей группы (группировка по дню).
    for (const r of rows) expect(groups.some((g) => r.includes(g))).toBe(true);

    const type = rows[0].split(',')[0];
    await setHistorySearch(type);
    await driver.waitUntil(async () => {
      const rs = await historyRows();
      return rs.length > 0 && rs.every((x) => x.startsWith(`${type}, `));
    }, { timeout: 15000, timeoutMsg: `поиск «${type}» не отфильтровал историю` });

    await setHistorySearch('zzzqq');
    await expect(byTextContains('לא נמצאו תפילות')).toBeDisplayed({ wait: 15000 });
    expect((await historyRows()).length).toBe(0);
    await setHistorySearch('');
    await driver.waitUntil(async () => (await historyRows()).length > 0, { timeout: 15000, timeoutMsg: 'после очистки нет строк' });
  });

  it('RD-01c Повторная запись: «סיים תפילה» у уже записанной сегодня молитвы → «התפילה כבר נרשמה היום»; «ביטול» — счётчики не меняются; «רשום שוב» (QA_RECORD_PRAYER=1) → +1 #6a86f7e5 F-41 AC3 @data', async function () {
    await goHome();
    const today0 = await counter('תפילות היום');
    const total0 = await counter('סה״כ תפילות');
    if (today0 === 0) skipWith(this, 'сегодня записей нет — нечего повторять (нужна хотя бы одна завершённая сегодня молитва)');
    await scrollToText('תפילות אחרונות');
    const prayer = await newestRecentPrayer();
    if (!prayer) skipWith(this, 'нет блока «תפילות אחרונות»');

    await openCatalogPrayer(prayer!);
    expect(await tapFinish()).toBe('already');
    await expect(byTextContains(REPEAT_TITLE)).toBeDisplayed();
    expect(await shown(button(REPEAT_AGAIN))).toBe(true);
    expect(await shown(button('ביטול'))).toBe(true);
    await (await button('ביטול')).click();
    await expect(byTextContains(REPEAT_TITLE)).not.toBeDisplayed({ wait: 10000 });
    await expect(byTextMatches('\\d+ מתוך \\d+')).toBeExisting();   // остались в молитве
    await goHome();
    expect(await counter('תפילות היום')).toBe(today0);
    expect(await counter('סה״כ תפילות')).toBe(total0);

    if (!recordAllowed()) { console.log('[RD-01c] «רשום שוב» не нажат: QA_RECORD_PRAYER≠1'); return; }
    await openCatalogPrayer(prayer!);
    expect(await tapFinish()).toBe('already');
    await (await button(REPEAT_AGAIN)).click();
    await (await byText(FINISH_TITLE)).waitForDisplayed({ timeout: 20000 });
    for (let i = 0; i < 3; i++) {   // «המשך» → окно достижения/уровня → «חזרה למסך ראשי»
      const b = await visibleActionButtons([BACK_HOME, 'המשך']);
      if (!b.length) break;
      await (await button(b[0])).click();
      if (b[0] === BACK_HOME) break;
    }
    await goHome();
    expect(await counter('סה״כ תפילות')).toBe(total0 + 1);
    expect(await counter('תפילות היום')).toBe(today0 + 1);
  });

  it('RD-01d «התחל תפילה»: до начала окна («<תפילה> מתחילה ב-HH:MM») неактивна; в окне активна и открывает эту молитву в нусахе главной #6a86f7e9 F-98 AC3 @time @prod-safe', async function () {
    await goHome();
    const start = await button('התחל תפילה');
    await start.waitForExist({ timeout: 20000 });
    const nusachHome = (await labelOf((await byTextMatches('נוסח (אשכנז|ספרד)')) as unknown as WebdriverIO.Element)).replace('נוסח ', '');
    const startsAt = await byTextMatches('.+ מתחילה ב-\\d{1,2}:\\d{2}');
    if (await shown(startsAt)) {
      const line = await labelOf(startsAt as unknown as WebdriverIO.Element);
      const [, hh, mm] = line.match(/(\d{1,2}):(\d{2})/)!;
      const now = await deviceClock();
      const before = now.h * 60 + now.m < Number(hh) * 60 + Number(mm);
      console.log(`[RD-01d] «${line}», сейчас ${now.h}:${now.m}`);
      if (!before) skipWith(this, `«${line}» видна, но время уже наступило — повторить вне окна`);
      expect(await start.isEnabled()).toBe(false);
      return;
    }
    // В окне молитвы: название ближайшей молитвы на главной (крупный текст под приветствием).
    const ns = await nodes();
    const title = ns.filter((n) => ['שחרית', 'מנחה', 'ערבית'].includes(n.label) && n.y < 400).sort((a, b) => a.y - b.y)[0]?.label;
    expect(await start.isEnabled()).toBe(true);
    await start.click();
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForExist({ timeout: 20000 });
    expect(await shownNusach()).toBe(`${nusachHome}י`);   // «נוסח אשכנז» → «הנוסח המוצג: אשכנזי»
    if (title) {
      // Имя открытой молитвы — в окне «הסבר על התפילה»: «על תפילת <название>» (S-21).
      await headerTap('הסבר על התפילה');
      await expect(byTextContains(`על תפילת ${title}`)).toBeDisplayed({ wait: 15000 });
      await (await button('סגירה')).click();
    }
  });
});
